css:
.cat-tabs{display:inline-flex;align-items:center;gap:5px}
.cat-tab{display:inline-flex;align-items:center;gap:7px;height:30px;padding:0 12px;border-radius:7px;border:1px solid transparent;font:500 var(--cat-font-size-base) var(--cat-font-family-ui);color:var(--cat-color-ink-mid);background:transparent;cursor:pointer;white-space:nowrap;transition:background var(--cat-motion-fast) ease,color var(--cat-motion-fast) ease,box-shadow var(--cat-motion-med) var(--cat-motion-ease-out)}
.cat-tab:hover{background:rgba(255,255,255,.35);color:var(--cat-color-ink-hi)}
.cat-tab.is-active{background:var(--cat-semantic-tab-a);border-color:rgba(255,255,255,.85);color:var(--cat-color-ink-hi);font-weight:var(--cat-font-weight-semibold);box-shadow:0 1px 2px rgba(25,35,65,.08)}
[data-cat-tabs]{position:relative}
.cat-tabs>.cat-glider{top:0;bottom:0;left:0;border-radius:7px;background:var(--cat-semantic-tab-a);border:1px solid var(--cat-color-stroke-dark);box-shadow:0 1px 2px rgba(25,35,65,.10);transition:transform 240ms var(--cat-motion-spring),width 240ms var(--cat-motion-spring),opacity 150ms ease;opacity:0;z-index:0;width:max-content}
.cat-tab{position:relative;z-index:1;background:none!important;border-color:transparent!important;box-shadow:none!important}
.cat-tab.is-active{color:var(--cat-color-ink-hi);font-weight:var(--cat-font-weight-semibold)}
.cat-tab:not(.is-active):hover{background:rgba(255,255,255,.35)!important}
